// === Tab: mySketch ===
// Attractor_28.0

let N = 10000 ; let M = 10 ; 
let A[] = new Array(M) ; let FX[] = new Array(M) ; let FY[] = new Array(M) ; 
let X[] = new Array(N) ; let Y[] = new Array(N) ; let I ; let II ; let dX ; let dY ;

function setup(){	
	createCanvas(900, 900) ; noSmooth() ; background(200) ; stroke(200,100,100,200) ;  
	for ( I = 0 ; I < N ; I++ ){ X[I] = random(0,9000) ; Y[I] = random(0,9000) ; if ( pow(X[I]-450,2)+pow(Y[I]-450,2) > pow(300,2) ){ I = I-1 ; } } 
	for ( II = 0 ; II < M ; II++ ){ A[II] = random(0,1) ; FX[II] = random(0,0.1) ; FY[II] = random(0,0.1) ;	}
}//setup()

function draw(){ 
	for ( I = 0 ; I < N ; I++ ){ 
		point(X[I],Y[I]) ; dX = 0 ; dY = 0 ;
		for ( II = 0 ; II < M ; II++ ){
			dX = dX + (A[II]*sin(+Y[I]*FY[II])) ; dY = dY + (A[II]*sin(+X[I]*FX[II])) ;
		}//let X[I] = X[I]+dX ; Y[I] = Y[I]+dY ;
		if ( X[I] > 900 ){ X[I] =   0 ; }
  	if ( X[I] <   0 ){ X[I] = 900 ; }
  	if ( Y[I] > 900 ){ Y[I] =   0 ; }
  	if ( Y[I] <   0 ){ Y[I] = 900 ; }
	} //I
}//draw()

function mousePressed(){ setup() ; }

